import numpy as np

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    if len(unvisited_nodes) == 0:
        return destination_node

    if len(unvisited_nodes) == 1:
        return int(unvisited_nodes[0])

    candidates = unvisited_nodes
    n = len(candidates)

    immediate_costs = distance_matrix[current_node, candidates]
    dest_costs = distance_matrix[candidates, destination_node]

    direct_dist = distance_matrix[current_node, destination_node]
    progress = np.maximum(direct_dist - dest_costs, 0.0)

    min_conn_costs = np.zeros(n)
    for i, u in enumerate(candidates):
        others = candidates[candidates != u]
        if len(others) > 0:
            min_conn_costs[i] = np.mean(distance_matrix[u, others])
        else:
            min_conn_costs[i] = 0.0

    weight_progress = 0.5
    weight_connectivity = 0.1

    scores = immediate_costs + weight_progress * progress + weight_connectivity * min_conn_costs

    dest_mask = (candidates == destination_node)
    if np.any(dest_mask) and n > 1:
        penalty = 10.0 * (n ** 2)
        scores[dest_mask] += penalty

    min_index = np.argmin(scores)
    return int(candidates[min_index])

