def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    if len(unvisited_nodes) == 0:
        return -1
    if len(unvisited_nodes) == 1:
        return int(unvisited_nodes[0])

    def mst_weight(nodes):
        if len(nodes) <= 1:
            return 0.0

        n = len(nodes)
        visited = [False] * n
        visited[0] = True
        dist_to_mst = [float('inf')] * n
        dist_to_mst[0] = 0.0

        for i in range(1, n):
            dist_to_mst[i] = distance_matrix[nodes[0], nodes[i]]

        total_weight = 0.0

        for _ in range(n - 1):
            min_val = float('inf')
            next_idx = -1
            for i in range(n):
                if not visited[i] and dist_to_mst[i] < min_val:
                    min_val = dist_to_mst[i]
                    next_idx = i

            if next_idx == -1:
                break

            total_weight += min_val
            visited[next_idx] = True

            for i in range(n):
                if not visited[i]:
                    d = distance_matrix[nodes[next_idx], nodes[i]]
                    if d < dist_to_mst[i]:
                        dist_to_mst[i] = d

        return total_weight

    best_node = -1
    best_score = float('inf')

    for i, candidate in enumerate(unvisited_nodes):
        d_curr = distance_matrix[current_node, candidate]

        remaining = [u for u in unvisited_nodes if u != candidate]

        if len(remaining) == 0:
            future_cost = distance_matrix[candidate, destination_node]
            final_score = d_curr + future_cost
        else:
            nodes_for_mst = list(remaining) + [destination_node]
            mst_val = mst_weight(nodes_for_mst)

            # Entry cost: min distance from candidate to any node in remaining structure
            min_conn = min(distance_matrix[candidate, v] for v in nodes_for_mst)

            # Centrality bonus: reward nodes that are close to other unvisited nodes
            min_to_rem = min(distance_matrix[candidate, v] for v in remaining)
            bonus = 0.1 * min_to_rem

            future_cost = mst_val + 0.5 * min_conn - bonus

            final_score = d_curr + future_cost

        if final_score < best_score:
            best_score = final_score
            best_node = candidate

    return int(best_node)

