def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    n_remaining = len(unvisited_nodes)

    if n_remaining == 0:
        return current_node

    if n_remaining == 1:
        return int(unvisited_nodes[0])

    if n_remaining <= 13:
        n = n_remaining
        full_mask = (1 << n) - 1
        dp = np.full((1 << n, n), np.inf)

        for i in range(n):
            node = unvisited_nodes[i]
            dp[1 << i, i] = distance_matrix[node][destination_node]

        for mask in range(1, full_mask + 1):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                if mask == (1 << i):
                    continue

                rem_mask = mask & ~(1 << i)
                best_val = np.inf
                for k in range(n):
                    if rem_mask & (1 << k):
                        cost = distance_matrix[unvisited_nodes[i]][unvisited_nodes[k]] + dp[rem_mask, k]
                        if cost < best_val:
                            best_val = cost
                dp[mask, i] = best_val

        total_costs = np.empty(n)
        for j in range(n):
            node = unvisited_nodes[j]
            total_costs[j] = distance_matrix[current_node][node] + dp[full_mask, j]

        return int(unvisited_nodes[np.argmin(total_costs)])

    d_cur = distance_matrix[current_node, unvisited_nodes]
    d_dest = distance_matrix[unvisited_nodes, destination_node]
    sub_matrix = distance_matrix[np.ix_(unvisited_nodes, unvisited_nodes)]

    # 2-step lookahead
    X2 = sub_matrix + d_dest[None, :]
    np.fill_diagonal(X2, np.inf)
    f2 = np.min(X2, axis=1)

    # 3-step lookahead
    X3 = sub_matrix + f2[None, :]
    np.fill_diagonal(X3, np.inf)
    f3 = np.min(X3, axis=1)

    # Average distance to other unvisited nodes (excluding self)
    avg_dist = (np.sum(sub_matrix, axis=1) - np.diag(sub_matrix)) / max(n_remaining - 1, 1)

    # Regret: difference between candidate's avg_dist and global mean
    global_mean = np.mean(avg_dist)
    regret = avg_dist - global_mean

    scale = 1.0 / (n_remaining + 1)
    scores = d_cur + 0.8 * scale * f3 + 0.3 * scale * regret

    return int(unvisited_nodes[np.argmin(scores)])

