        best_node = candidates[0]

        for v in candidates:
            cost = distance_matrix[current_node, v]
            remaining = [u for u in candidates if u != v]

            if not remaining:
                total_cost = cost + distance_matrix[v, destination_node]
            else:
                # Recursive helper for small sets
                def dfs(curr, unvisited):
                    if not unvisited:
                        return distance_matrix[curr, destination_node]

                    min_cost = float('inf')
                    for u in unvisited:
                        next_cost = distance_matrix[curr, u] + dfs(u, [x for x in unvisited if x != u])
                        if next_cost < min_cost:
                            min_cost = next_cost
                    return min_cost

                total_cost = cost + dfs(v, remaining)

            if total_cost < best_score:
                best_score = total_cost
                best_node = v

        return int(best_node)

    elif n <= 20:
        # 2-step lookahead with greedy estimation for remaining
        scores = np.zeros(n)

        for i, v in enumerate(candidates):
            cost_to_v = distance_matrix[current_node, v]

            # Estimate cost from v to destination visiting all remaining nodes
            # Use greedy nearest neighbor for the remaining part
            remaining = list(candidates)
            remaining.pop(i)

            if not remaining:
                rem_cost = distance_matrix[v, destination_node]
            else:
                rem_cost = 0.0
                curr = v
                rem_set = set(remaining)

                while rem_set:
                    best_next = -1
                    best_dist = float('inf')
                    for u in rem_set:
