def _dp_shortest_path(start, nodes, dist, dest):
    """
    Computes the cost of the shortest path starting at `start`, visiting all nodes in `nodes` exactly once,
    and ending at `dest`.
    Uses bitmask DP.
    """
    if not nodes:
        return dist[start, dest]

    n = len(nodes)
    # dp[mask][i] = min cost to reach node i (index in nodes) having visited mask of nodes
    # We start at `start`, so initial mask is 0.
    # To simplify, we can just run DP from start.

    # Map node ID to index in nodes
    node_to_idx = {node: i for i, node in enumerate(nodes)}

    size = 1 << n
    dp = np.full((size, n), np.inf)

    # Initialize: from start to each node in nodes
    for i, node in enumerate(nodes):
        dp[1 << i, i] = dist[start, node]

    # Fill DP table
    for mask in range(1, size):
        for i in range(n):
            if not (mask & (1 << i)):
                continue
            if dp[mask, i] == np.inf:
                continue

            # Try moving to j not in mask
            for j in range(n):
                if mask & (1 << j):
                    continue

                new_mask = mask | (1 << j)
                new_cost = dp[mask, i] + dist[nodes[i], nodes[j]]
                if new_cost < dp[new_mask, j]:
                    dp[new_mask, j] = new_cost

    # Find min cost to end at any node and then go to dest
    full_mask = size - 1
    min_final_cost = np.inf
    for i in range(n):
        cost_to_dest = dist[nodes[i], dest]
        total = dp[full_mask, i] + cost_to_dest
        if total < min_final_cost:
            min_final_cost = total

    return min_final_cost

def _two_opt(path, dist):
    """Apply 2-opt optimization to a path."""
    n = len(path)
    if n < 3:
        return path
    improved = True
    while improved:
        improved = False
        for i in range(1, n - 2):
            for j in range(i + 1, n - 1):
                if i == j:
                    continue
                old_cost = dist[path[i], path[i+1]] + dist[path[j], path[j+1]]
                new_cost = dist[path[i], path[j]] + dist[path[i+1], path[j+1]]
                if new_cost < old_cost - 1e-9:
                    path = path[:i+1] + path[i+1:j+1][::-1] + path[j+1:]
                    improved = True
                    break
            if improved:
                break
    return path

def _nn_path(start, unvisited, dist, dest):
    """Build a nearest-neighbor path from start through all unvisited nodes to dest, then apply 2-opt."""
    path = [start]
    rem = list(unvisited)
    curr = start
    while rem:
        d = dist[curr, rem]
        nxt = rem[np.argmin(d)]
        path.append(nxt)
        rem.remove(nxt)
        curr = nxt
    path.append(dest)
    path = _two_opt(path, dist)
    return path

def select_next_node(current_node: int, destination_node: int, unvisited_nodes: np.ndarray, distance_matrix: np.ndarray) -> int:
    """
    Select the next node using a tiered strategy:
    1. Exact DP for small sets (n <= 10).
    2. 1-step lookahead with NN+2-opt for medium sets (n <= 25).
    3. Blended heuristic for large sets.
    """
    if len(unvisited_nodes) == 0:
        return current_node

    if len(unvisited_nodes) == 1:
        return int(unvisited_nodes[0])

    n = len(unvisited_nodes)
    candidates = unvisited_nodes

    if n <= 10:
        # Exact DP
        best_score = float('inf')
        best_node = candidates[0]

        for v in candidates:
            remaining = [u for u in candidates if u != v]
            cost_to_v = distance_matrix[current_node, v]
            rem_cost = _dp_shortest_path(v, remaining, distance_matrix, destination_node)
            total_cost = cost_to_v + rem_cost

            if total_cost < best_score:
                best_score = total_cost
                best_node = v

        return int(best_node)

    elif n <= 25:
        # 1-step lookahead with NN+2-opt
        best_score = float('inf')
        best_node = candidates[0]

        for v in candidates:
            remaining = [u for u in candidates if u != v]
            cost_to_v = distance_matrix[current_node, v]

            if not remaining:
                total_cost = cost_to_v + distance_matrix[v, destination_node]
            else:
                path = _nn_path(v, remaining, distance_matrix, destination_node)
                path_cost = sum(distance_matrix[path[i], path[i+1]] for i in range(len(path)-1))
                total_cost = cost_to_v + path_cost

            if total_cost < best_score:
                best_score = total_cost
                best_node = v

        return int(best_node)

    else:
        # Large N: Blended heuristic
        d_cur_to_v = distance_matrix[current_node, candidates]
        d_v_to_dest = distance_matrix[candidates, destination_node]

        # Weight 0.5 balances immediate distance and destination proximity
        scores = d_cur_to_v + 0.5 * d_v_to_dest

        best_idx = np.argmin(scores)
        return int(candidates[best_idx])

